/**
 * Freestyle VM Setup Script
 *
 * Spins up a VM with Python (via uv), installs pandas/numpy/requests,
 * initialises a SQLite database with seed data, then snapshots the VM.
 *
 * References:
 *   - https://docs.freestyle.sh/v2/vms
 *   - https://docs.freestyle.sh/v2/vms/integrations/python/uv
 *   - https://docs.freestyle.sh/v2/vms/templates-snapshots
 */

import { freestyle, VmSpec } from "freestyle-sandboxes";
import { VmUv } from "@freestyle-sh/with-uv";

async function main() {
  console.log("Creating VM with Python (uv)...");

  const { vm, vmId } = await freestyle.vms.create(
    new VmSpec().with("uv", new VmUv({ pythonVersion: "3.12" }))
  );

  console.log(`VM created: ${vmId}`);

  // Install packages and initialise SQLite database with seed data
  // uv runCode supports PEP 723 inline script dependencies via `# /// script` block
  console.log("Installing packages and initialising SQLite database...");
  const dbSetup = await vm.uv.runCode({
    code: `
# /// script
# dependencies = ["pandas", "numpy", "requests"]
# ///
import sqlite3
import json

db_path = "/data/app.db"

import os
os.makedirs("/data", exist_ok=True)

conn = sqlite3.connect(db_path)
cur = conn.cursor()

cur.execute("""
  CREATE TABLE IF NOT EXISTS users (
    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    name  TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE
  )
""")

cur.execute("""
  CREATE TABLE IF NOT EXISTS products (
    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    name  TEXT NOT NULL,
    price REAL NOT NULL
  )
""")

users = [
  ("Alice",   "alice@example.com"),
  ("Bob",     "bob@example.com"),
  ("Charlie", "charlie@example.com"),
]
cur.executemany("INSERT OR IGNORE INTO users (name, email) VALUES (?, ?)", users)

products = [
  ("Widget",  9.99),
  ("Gadget",  24.99),
  ("Doohickey", 4.99),
]
cur.executemany("INSERT OR IGNORE INTO products (name, price) VALUES (?, ?)", products)

conn.commit()

user_count    = cur.execute("SELECT COUNT(*) FROM users").fetchone()[0]
product_count = cur.execute("SELECT COUNT(*) FROM products").fetchone()[0]
conn.close()

import json
print(json.dumps({"db_path": db_path, "users": user_count, "products": product_count}))
`,
  });

  if (dbSetup.statusCode !== 0) {
    throw new Error(`DB setup failed:\n${dbSetup.stderr}`);
  }
  console.log("Database initialised:", dbSetup.result);

  // Verify packages are importable
  console.log("Verifying installed packages...");
  const verify = await vm.uv.runCode({
    code: `
# /// script
# dependencies = ["pandas", "numpy", "requests"]
# ///
import json
import pandas as pd
import numpy as np
import requests

print(json.dumps({
  "pandas":   pd.__version__,
  "numpy":    np.__version__,
  "requests": requests.__version__,
}))
`,
  });

  if (verify.statusCode !== 0) {
    throw new Error(`Package verification failed:\n${verify.stderr}`);
  }
  console.log("Package versions:", verify.result);

  // Snapshot the VM
  console.log("Snapshotting VM...");
  const { snapshotId } = await vm.snapshot();
  console.log(`Snapshot created: ${snapshotId}`);
  console.log("\nVM is ready. Use this snapshot ID for the next step:");
  console.log(`  snapshotId: ${snapshotId}`);
  console.log(`  vmId:       ${vmId}`);
}

main().catch((err) => {
  console.error("Setup failed:", err);
  process.exit(1);
});

